import{_ as r,o as a,c as t,a2 as o}from"./chunks/framework.IIAdu7fg.js";const u=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-10-23","description":"证书信任的未闭合边界、沙箱策略修复、hook 接入、恢复点与升级续跑。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-10-23","description":"证书信任的未闭合边界、沙箱策略修复、hook 接入、恢复点与升级续跑。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-10-23.md","filePath":"zh/runtime/daily-intelligence/2026-10-23.md","lastUpdated":null}'),l={name:"zh/runtime/daily-intelligence/2026-10-23.md"};function n(s,e,p,i,h,g){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-核心研究与竞品动态-·-2026-10-23" tabindex="-1">Agent 核心研究与竞品动态 · 2026-10-23 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-10-23" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-10-23&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 增量窗口：2026-10-22 10:01:57 至 2026-10-23 09:56:25。按分来源成功水位核查；此前未穷尽的来源保留更早 pending 窗口。状态按实际读取时刻核验，非原子快照。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>本轮确认 <strong>14 组有技术/产品价值的新增</strong>。优先关注证书修复仍未闭合的系统边界、Claude Code 的沙箱/配置保护修复，以及 hook 接入、恢复点、升级续跑和调用证据的变化。所有 CodeFlowMu/FCoP 关联均为待验证研究判断；本轮本地实验、文章、正式开发评审和外部互动均为 <strong>0</strong>。</p><h2 id="_1-证书信任修复跨项目推进-openhands-系统证书补丁仍开放" tabindex="-1">1. 证书信任修复跨项目推进，OpenHands 系统证书补丁仍开放 <a class="header-anchor" href="#_1-证书信任修复跨项目推进-openhands-系统证书补丁仍开放" aria-label="Permalink to &quot;1. 证书信任修复跨项目推进，OpenHands 系统证书补丁仍开放&quot;">​</a></h2><p><strong>状态: OpenHands SDK v1.58.1 RELEASED; #6162 MERGED; #6167 OPEN / NOT MERGED; DSPy #10703, #10711 MERGED; Phoenix evals v3.9.3 RELEASED</strong></p><p><a href="https://discuss.python.org/t/information-for-python-users-regarding-emudhra-emsign-ca-certificate-security-incident/109576" target="_blank" rel="noreferrer">Python security advisory</a> · <a href="https://github.com/OpenHands/software-agent-sdk/releases/tag/v1.58.1" target="_blank" rel="noreferrer">v1.58.1</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6162" target="_blank" rel="noreferrer">#6162</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6167" target="_blank" rel="noreferrer">#6167</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10703" target="_blank" rel="noreferrer">#10703</a> · <a href="https://github.com/stanfordnlp/dspy/pull/10711" target="_blank" rel="noreferrer">#10711</a> · <a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-evals-v3.9.3" target="_blank" rel="noreferrer">arize-phoenix-evals-v3.9.3</a></p><p>本轮新增是下游修复及其未闭合边界，不把 10 月 20 日的 Python 安全公告冒充今天的新事故。OpenHands v1.58.1 已更新 Python 依赖与安装器信任；后续 #6167 指出先前 Debian snapshot 尚未移除 emSign G3，提出再推进系统证书快照和构建阶段的 Python 基础镜像，当前仍未合入。DSPy #10703 之后又合入 #10711，以临时容器 overlay 补齐独立发布容器的 pip 与 OS 信任；其验证未做真实上传或凭据交换。Phoenix evals 3.9.3 也列出证书约束和 LiteLLM 排除。未检查本地是否暴露。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 依赖包、安装器内置 bundle、系统证书库和独立发布容器必须分别验证。对 CodeFlowMu/FCoP 是待验的构建来源与运行镜像证据议题，不能因一个版本已发行就写成整条信任链已修复。</p><p><strong>互动判断与技术切入:</strong> 值得互动：怎样把各层 trust-store 的实际指纹和构建镜像身份写入修复验收证据？</p><h2 id="_2-claude-code-2-1-309-修复跨入口与真实路径的策略缺口" tabindex="-1">2. Claude Code 2.1.309 修复跨入口与真实路径的策略缺口 <a class="header-anchor" href="#_2-claude-code-2-1-309-修复跨入口与真实路径的策略缺口" aria-label="Permalink to &quot;2. Claude Code 2.1.309 修复跨入口与真实路径的策略缺口&quot;">​</a></h2><p><strong>状态: v2.1.309 RELEASED · 2026-10-23 06:18 Asia/Shanghai</strong></p><p><a href="https://github.com/anthropics/claude-code/releases/tag/v2.1.309" target="_blank" rel="noreferrer">v2.1.309</a></p><p>正式发行说明列出：沙箱命令的 shell 启动文件不应在沙箱外执行；symlink 后的真实路径须落实 denyWrite；不能通过沙箱命令或自动接受编辑修改 --mcp-config 指定文件；被禁用的 MCP server 不能被后续审批重新连接；并修复重定向失败、子 shell 和隔离 worktree 的权限判定。这里是上游发行声明，未在本机复现。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 权限对象必须覆盖真实路径、配置文件及不同工具入口。对 CodeFlowMu/FCoP 的价值是设计同一效果经不同入口产生时的对照实验。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：符号链接解析、配置保护与工具入口规则怎样共享同一授权对象？</p><h2 id="_3-赵越-从规则脚本推进到-codex-pretooluse-的注册与信任边界" tabindex="-1">3. 赵越：从规则脚本推进到 Codex PreToolUse 的注册与信任边界 <a class="header-anchor" href="#_3-赵越-从规则脚本推进到-codex-pretooluse-的注册与信任边界" aria-label="Permalink to &quot;3. 赵越：从规则脚本推进到 Codex PreToolUse 的注册与信任边界&quot;">​</a></h2><p><strong>状态: DEFAULT-BRANCH COMMITS · 2026-10-23 06:33 Asia/Shanghai</strong></p><p><a href="https://github.com/yzhao062/anywhere-agents/commit/f6988cfb4c070a8d774cdf31f738224800b8fce3" target="_blank" rel="noreferrer">anywhere-agents commit</a> · <a href="https://github.com/yzhao062/agent-config/commit/9c75f10ff0a404083c7f7f79f0594c789c22379c" target="_blank" rel="noreferrer">agent-config commit</a> · <a href="https://github.com/yzhao062/anywhere-agents/blob/main/docs/guard-hook.md" target="_blank" rel="noreferrer">Guard Hook</a></p><p>两个提交均由 yzhao062 署名。POSIX bootstrap 把 guard 注册到 Codex hooks.json，覆盖 Bash 和 apply_patch；补丁按新增行和修改后的代码围栏判定。原 ask 分支在此改为 deny，并提示用户使用其本人拥有的交互路径。关键限制来自作者文档和 diff：Windows 入口尚未注册；注册不等于用户已信任；信任指纹涵盖 hook 定义而非脚本正文；--ignore-user-config 的 reviewer 不带该用户钩子；崩溃、超时或格式错误仍可能放行。没有修改本机 hooks 或信任配置。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 这是实际接入变化，区别于昨天的 shell 写入识别扩展。CodeFlowMu/FCoP 可研究注册、信任、代码版本与每次调用实际执行四层证据，尚未验证本地产品。</p><p><strong>互动判断与技术切入:</strong> 值得互动：脚本更新不改变已信任定义时，怎样保留可追溯的实际脚本身份和失败放行记录？</p><h2 id="_4-codex-环境所属必需-hook、配置来源身份与-mcp-网络策略协商" tabindex="-1">4. Codex：环境所属必需 hook、配置来源身份与 MCP 网络策略协商 <a class="header-anchor" href="#_4-codex-环境所属必需-hook、配置来源身份与-mcp-网络策略协商" aria-label="Permalink to &quot;4. Codex：环境所属必需 hook、配置来源身份与 MCP 网络策略协商&quot;">​</a></h2><p><strong>状态: #56304, #56314, #56295, #56278, #56234, #56132, #56124, #56154 MERGED; stable release inclusion NOT VERIFIED</strong></p><p><a href="https://github.com/openai/codex/pull/56304" target="_blank" rel="noreferrer">#56304</a> · <a href="https://github.com/openai/codex/pull/56314" target="_blank" rel="noreferrer">#56314</a> · <a href="https://github.com/openai/codex/pull/56295" target="_blank" rel="noreferrer">#56295</a> · <a href="https://github.com/openai/codex/pull/56278" target="_blank" rel="noreferrer">#56278</a> · <a href="https://github.com/openai/codex/pull/56234" target="_blank" rel="noreferrer">#56234</a> · <a href="https://github.com/openai/codex/pull/56132" target="_blank" rel="noreferrer">#56132</a> · <a href="https://github.com/openai/codex/pull/56124" target="_blank" rel="noreferrer">#56124</a> · <a href="https://github.com/openai/codex/pull/56154" target="_blank" rel="noreferrer">#56154</a></p><p>环境所属 hook 使用所属环境的目录与平台，隐藏控制器 transcript 路径，不能批准权限请求；必需 hook 无法加载时阻止配置进入就绪。自定义配置服务使用按端点与授权身份隔离的缓存，获取配置不触发交互登录。MCP 网络策略元数据需可信来源及会话能力协商，移除调用者伪造字段，按调用捕获的权限快照计算，解析失败在发送前失败；现有未注入 provider 的调用者不自动启用。另有输入被 hook 接受后再发遥测、取消 MCP 请求及向父订阅者转发 Guardian 事件。已读核心 diff；仅确认合入。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 策略配置存在、所属环境正确、调用时协商成功，是三个独立事实。对 CodeFlowMu 多 Host 的待验价值在于授权来源隔离、必需策略就绪检查与调用证据一致性。</p><p><strong>互动判断与技术切入:</strong> 值得研究后互动：恢复连接后能力改变时，怎样保留单次调用快照而拒绝伪造的策略字段？</p><h2 id="_5-paperclip-加密恢复点、保留周期与-provider-所有的重试工作区" tabindex="-1">5. Paperclip：加密恢复点、保留周期与 provider 所有的重试工作区 <a class="header-anchor" href="#_5-paperclip-加密恢复点、保留周期与-provider-所有的重试工作区" aria-label="Permalink to &quot;5. Paperclip：加密恢复点、保留周期与 provider 所有的重试工作区&quot;">​</a></h2><p><strong>状态: #17238, #17241, #17248, #17257, #17252, #17259, #17216 MERGED; #17267 OPEN / NOT MERGED; #17050 remains OPEN</strong></p><p><a href="https://github.com/paperclipai/paperclip/pull/17238" target="_blank" rel="noreferrer">#17238</a> · <a href="https://github.com/paperclipai/paperclip/pull/17241" target="_blank" rel="noreferrer">#17241</a> · <a href="https://github.com/paperclipai/paperclip/pull/17248" target="_blank" rel="noreferrer">#17248</a> · <a href="https://github.com/paperclipai/paperclip/pull/17257" target="_blank" rel="noreferrer">#17257</a> · <a href="https://github.com/paperclipai/paperclip/pull/17252" target="_blank" rel="noreferrer">#17252</a> · <a href="https://github.com/paperclipai/paperclip/pull/17259" target="_blank" rel="noreferrer">#17259</a> · <a href="https://github.com/paperclipai/paperclip/pull/17216" target="_blank" rel="noreferrer">#17216</a> · <a href="https://github.com/paperclipai/paperclip/pull/17267" target="_blank" rel="noreferrer">#17267</a> · <a href="https://github.com/paperclipai/paperclip/pull/17050" target="_blank" rel="noreferrer">#17050</a></p><p>恢复点从库和生命周期表推进到清理/恢复接线，保存远端无法重建的未推送、未提交等工作，嵌套 checkout 也有独立恢复点；该模式默认关闭，其他分支、未保存提交草稿等仍可阻止清理。provider 新重试用稳定 attempt 身份、版本检查和已验证恢复文件保留失败工作区。另已合入 Claude onboarding 的兼容 runtime 准备，以及按明确授权名称把服务密钥交给 Codex shell 的修复。#17267 的“确认沙箱已不存在后继续 Retry”仍开放；昨天的 OTLP 凭据 #17050 也未合入。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> CodeFlowMu/FCoP 可研究恢复点身份、保留期、失败证据和 provider 存储语义；加密保存不等于任意工作区都已可安全删除。</p><p><strong>学习价值: 高 · 竞争风险: 高。</strong> 维持主雷达高关注，提高恢复与多仓库工作区成熟度判断；默认关闭和开放修复保留为边界。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：如何用恢复回执证明重开后的工作与清理前一致，并明确恢复点过期后的行为？</p><h2 id="_6-staffdeck-源码升级先准备-runtime-失败时保留旧服务" tabindex="-1">6. StaffDeck：源码升级先准备 runtime，失败时保留旧服务 <a class="header-anchor" href="#_6-staffdeck-源码升级先准备-runtime-失败时保留旧服务" aria-label="Permalink to &quot;6. StaffDeck：源码升级先准备 runtime，失败时保留旧服务&quot;">​</a></h2><p><strong>状态: #288 MERGED; source-upgrade change, no newly verified installer release</strong></p><p><a href="https://github.com/OpenBMB/StaffDeck/pull/288" target="_blank" rel="noreferrer">#288</a> · <a href="https://github.com/OpenBMB/StaffDeck/blob/main/INSTALL.md" target="_blank" rel="noreferrer">INSTALL.md</a></p><p>缺失 Harness v3 入口、依赖或 Python SDK 时，开发启动流程先准备 runtime 和前端，再停止旧服务；准备失败则退出并保留旧进程。PowerShell wrapper 优先原后端虚拟环境，外部 engine override 保留。上游报告做了真实 macOS 升级失败/恢复验收，Windows 环境选择仅由源码测试覆盖。本轮没有安装包实测，也不把昨天已到位的七个附件再算新增。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 对 CodeFlowMu 的学习价值在升级事务顺序、虚拟环境身份和失败保全；尚未完成本地对照实验。</p><p><strong>学习价值: 高 · 竞争风险: 高。</strong> 维持主雷达，提高源码升级可靠性判断；Windows 与签名成熟度仍待实测。</p><p><strong>互动判断与技术切入:</strong> 值得安装实验后互动：准备成功的判定能否覆盖 CLI、SDK 与真正启动的 backend 使用同一环境？</p><h2 id="_7-superset-更新后恢复会话-云端订阅凭据与-api-边界继续成形" tabindex="-1">7. Superset：更新后恢复会话，云端订阅凭据与 API 边界继续成形 <a class="header-anchor" href="#_7-superset-更新后恢复会话-云端订阅凭据与-api-边界继续成形" aria-label="Permalink to &quot;7. Superset：更新后恢复会话，云端订阅凭据与 API 边界继续成形&quot;">​</a></h2><p><strong>状态: #8451, #8786, #8796, #8768, #8767 MERGED; #8780, #8791 OPEN / NOT MERGED; Cloud remains internally gated</strong></p><p><a href="https://github.com/superset-sh/superset/pull/8451" target="_blank" rel="noreferrer">#8451</a> · <a href="https://github.com/superset-sh/superset/pull/8786" target="_blank" rel="noreferrer">#8786</a> · <a href="https://github.com/superset-sh/superset/pull/8796" target="_blank" rel="noreferrer">#8796</a> · <a href="https://github.com/superset-sh/superset/pull/8768" target="_blank" rel="noreferrer">#8768</a> · <a href="https://github.com/superset-sh/superset/pull/8767" target="_blank" rel="noreferrer">#8767</a> · <a href="https://github.com/superset-sh/superset/pull/8780" target="_blank" rel="noreferrer">#8780</a> · <a href="https://github.com/superset-sh/superset/pull/8791" target="_blank" rel="noreferrer">#8791</a> · <a href="https://github.com/superset-sh/superset/blob/main/docs/cloud-sandbox-considerations.md" target="_blank" rel="noreferrer">Cloud boundaries</a></p><p>只有用户主动安装更新才保存未完成聊天并在重启后继续，普通退出仍停止，暂停的提示保持暂停。Cloud Codex 使用独立于本机登录的 ChatGPT 会话，API 在锁下刷新，box 不拿 refresh token，以占位凭据由防火墙替换。box API allowlist 从 28 扩到 62，仍禁止可授予权限或访问其他机器的路径。环境创建改为显式选择，并按账单 feature 限额；PR 内拟议套餐数字不是已确认价格。迁移本地 Claude 到云端、重试风暴修复仍开放。当前官方仓库文档仍是内部 gate。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> CodeFlowMu 可研究升级恢复意图、凭据单一持有者、云端调用面的最小权限及商业配额的服务端执行。</p><p><strong>学习价值: 高 · 竞争风险: 高。</strong> 维持主雷达高关注，提高升级恢复和订阅凭据治理关注；不将内部 Cloud 或开放 PR 算公开交付。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：升级续跑如何避免旧进程仍写会话，以及 box 插件安装权限如何与跨机器影响区分？</p><h2 id="_8-engel-nyst-openhands-恢复计数、终端密钥隔离和-mcp-oauth-安装" tabindex="-1">8. Engel Nyst / OpenHands：恢复计数、终端密钥隔离和 MCP OAuth 安装 <a class="header-anchor" href="#_8-engel-nyst-openhands-恢复计数、终端密钥隔离和-mcp-oauth-安装" aria-label="Permalink to &quot;8. Engel Nyst / OpenHands：恢复计数、终端密钥隔离和 MCP OAuth 安装&quot;">​</a></h2><p><strong>状态: SDK v1.58.0 RELEASED; #5832, #6148 MERGED; OpenHands v1.31.0 RELEASED / #18780 MERGED</strong></p><p><a href="https://github.com/OpenHands/software-agent-sdk/releases/tag/v1.58.0" target="_blank" rel="noreferrer">v1.58.0</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/5832" target="_blank" rel="noreferrer">#5832</a> · <a href="https://github.com/OpenHands/software-agent-sdk/pull/6148" target="_blank" rel="noreferrer">#6148</a> · <a href="https://github.com/OpenHands/OpenHands/releases/tag/v1.31.0" target="_blank" rel="noreferrer">v1.31.0</a> · <a href="https://github.com/OpenHands/OpenHands/pull/18780" target="_blank" rel="noreferrer">#18780</a></p><p>enyst 的 #5832 在 judge 审计完成后才计轮数，恢复时修正保存计数；这里的 iteration 是已完成审计轮，不是所有尝试的硬上限，恢复仍可至少执行一轮。#6148 把其他终端已有的环境清理落实到 tmux 和 pane pool，移除 session/API/加密密钥变量。SDK 1.58.0 列出这些变化；应用 1.31.0 另修复通过 MCP server 自有 OAuth 安装仅 OAuth 的库条目。应用版本不据此等同于已消费 SDK 1.58.1 全部改动。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 对 FCoP，预算计数的定义与实际执行次数必须区分，凭据清理也要覆盖真正使用的终端后端。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：失败审计重试的资源成本如何单独记录，避免合法恢复被误读成预算内全部尝试？</p><h2 id="_9-mcp-typescript-缓存失效竞争仍在评审-skills-增加端到端证据" tabindex="-1">9. MCP TypeScript：缓存失效竞争仍在评审，Skills 增加端到端证据 <a class="header-anchor" href="#_9-mcp-typescript-缓存失效竞争仍在评审-skills-增加端到端证据" aria-label="Permalink to &quot;9. MCP TypeScript：缓存失效竞争仍在评审，Skills 增加端到端证据&quot;">​</a></h2><p><strong>状态: #3072 OPEN / NOT MERGED; #3065 MERGED; #3066 OPEN / NOT MERGED; Skills release NOT VERIFIED</strong></p><p><a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/3072" target="_blank" rel="noreferrer">#3072</a> · <a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/3065" target="_blank" rel="noreferrer">#3065</a> · <a href="https://github.com/modelcontextprotocol/typescript-sdk/pull/3066" target="_blank" rel="noreferrer">#3066</a></p><p>#3072 处理异步缓存读取期间收到 list_changed 后旧快照仍返回的竞争，以每 key 失效代次在 await 前后复核；完整 E2E 未声称全绿，且修复未合入。#3065 已把 Skills 的 41 项要求纳入跨传输与协议版本的 E2E；#3066 仍在提议改用 extensions: [skills]，其说明明确 Skills 尚未发行、setup 仍 experimental。不能把测试、提案和协议正式发布混为一谈。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> CodeFlowMu/FCoP 的待验议题是工具发现快照、异步失效和调用时能力的一致性。</p><p><strong>互动判断与技术切入:</strong> 值得互动：确定性挂起缓存读取的测试，如何覆盖旧工具定义和验证器索引一起失效？</p><h2 id="_10-langchain-core-1-7-改变原始-tool-call-参数流的语义" tabindex="-1">10. LangChain Core 1.7 改变原始 tool-call 参数流的语义 <a class="header-anchor" href="#_10-langchain-core-1-7-改变原始-tool-call-参数流的语义" aria-label="Permalink to &quot;10. LangChain Core 1.7 改变原始 tool-call 参数流的语义&quot;">​</a></h2><p><strong>状态: langchain-core==1.7.0 RELEASED; #41257 MERGED</strong></p><p><a href="https://github.com/langchain-ai/langchain/releases/tag/langchain-core==1.7.0" target="_blank" rel="noreferrer">langchain-core==1.7.0</a> · <a href="https://github.com/langchain-ai/langchain/pull/41257" target="_blank" rel="noreferrer">#41257</a></p><p>原始流事件改用 tool-call-delta 传递新参数片段，不能继续把 block-delta 或每次迭代当成累计快照；聚合的 .tool_calls.get() 和 .output 不变。发行说明为需要旧快照语义的用户给出 &lt;1.7 的暂时约束。未修改本地依赖。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 记录器、审批参数预览或回放器若误把 delta 当完整参数，会形成错误执行证据；这是 CodeFlowMu/FCoP 待验的事件兼容性议题。</p><p><strong>互动判断与技术切入:</strong> 值得验证后互动：增量流如何固定最终参数摘要，保证审批和实际调用使用同一完整对象？</p><h2 id="_11-gemini-cli-无终端环境的取消信号进入工具调度边界" tabindex="-1">11. Gemini CLI：无终端环境的取消信号进入工具调度边界 <a class="header-anchor" href="#_11-gemini-cli-无终端环境的取消信号进入工具调度边界" aria-label="Permalink to &quot;11. Gemini CLI：无终端环境的取消信号进入工具调度边界&quot;">​</a></h2><p><strong>状态: #29849 MERGED; v0.67.0-nightly.20261023.ga713410ab PRERELEASE</strong></p><p><a href="https://github.com/google-gemini/gemini-cli/pull/29849" target="_blank" rel="noreferrer">#29849</a> · <a href="https://github.com/google-gemini/gemini-cli/releases/tag/v0.67.0-nightly.20261023.ga713410ab" target="_blank" rel="noreferrer">v0.67.0-nightly.20261023.ga713410ab</a></p><p>非 TTY 的 CI、容器和脚本收到 SIGINT/SIGTERM 后会触发 AbortController，流中处理 UserCancelled，并在调度已排队工具前再检查取消状态，取消退出码统一为 130。该变动列入 nightly，不能写成稳定版已交付。本轮没有做信号/副作用复现。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 取消显示、进程信号和禁止新副作用应有一致边界，适合 CodeFlowMu worker 停止实验筛选。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：取消后到达的延迟 provider tool-call，如何留下被拒绝而未执行的证据？</p><h2 id="_12-copilot-cli-acp-恢复沿用沙箱设置-windows-shim-权限保持一致" tabindex="-1">12. Copilot CLI：ACP 恢复沿用沙箱设置，Windows shim 权限保持一致 <a class="header-anchor" href="#_12-copilot-cli-acp-恢复沿用沙箱设置-windows-shim-权限保持一致" aria-label="Permalink to &quot;12. Copilot CLI：ACP 恢复沿用沙箱设置，Windows shim 权限保持一致&quot;">​</a></h2><p><strong>状态: v1.0.103 RELEASED</strong></p><p><a href="https://github.com/github/copilot-cli/releases/tag/v1.0.103" target="_blank" rel="noreferrer">v1.0.103</a></p><p>正式发行说明修复 ACP 新建和恢复时遵守保存的 sandbox 设置及命令行开关；Windows npm.cmd 等 shim 沿用对应开发工具的沙箱授权。还修复断线重连丢失 Cloud 回复正文，并在同仓库的注册 worktree 间复用 MCP 工具快照。本轮没有验证缓存失效或本地隔离。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 对 CodeFlowMu，恢复后的权限姿态和平台命令别名映射应可核验；快照复用也不能据此推断授权可跨工作区通用。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：worktree 共享发现缓存时，如何隔离每个会话当前的沙箱与凭据权限？</p><h2 id="_13-phoenix-issue-to-pr-工厂与取消后沙箱清理" tabindex="-1">13. Phoenix：Issue-to-PR 工厂与取消后沙箱清理 <a class="header-anchor" href="#_13-phoenix-issue-to-pr-工厂与取消后沙箱清理" aria-label="Permalink to &quot;13. Phoenix：Issue-to-PR 工厂与取消后沙箱清理&quot;">​</a></h2><p><strong>状态: arize-phoenix-v20.25.0 RELEASED; #17020, #17169, #17166 MERGED</strong></p><p><a href="https://github.com/Arize-ai/phoenix/releases/tag/arize-phoenix-v20.25.0" target="_blank" rel="noreferrer">arize-phoenix-v20.25.0</a> · <a href="https://github.com/Arize-ai/phoenix/pull/17020" target="_blank" rel="noreferrer">#17020</a> · <a href="https://github.com/Arize-ai/phoenix/pull/17169" target="_blank" rel="noreferrer">#17169</a> · <a href="https://github.com/Arize-ai/phoenix/pull/17166" target="_blank" rel="noreferrer">#17166</a></p><p>仓库级 Managed Agents 工厂按 issue 标签和准入条件派发，要求失败测试/探针、控制变更范围，经 CI 和自动 review 反馈循环后再交人审；初始 PR 未验证真实 managed sessions 或完整 sandbox bootstrap，不把脚手架当成熟生产服务。后续将 factory lock 保存在独立状态分支。另修复 anyio/重复取消打断 sandbox delete：清理任务有独立生命期与关闭时的等待窗口，而调用者仍及时收到取消。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 对 CodeFlowMu/FCoP 的待验价值在任务准入、评审证据与控制状态分离，以及“用户已取消”和“资源已清理”的分别确认。</p><p><strong>互动判断与技术切入:</strong> 值得实验后互动：控制器重启和重复取消下，清理所有权及工厂派发身份怎样保持可恢复？</p><h2 id="_14-langfuse-区分写入完成与传输证据-并导出评分来源" tabindex="-1">14. Langfuse：区分写入完成与传输证据，并导出评分来源 <a class="header-anchor" href="#_14-langfuse-区分写入完成与传输证据-并导出评分来源" aria-label="Permalink to &quot;14. Langfuse：区分写入完成与传输证据，并导出评分来源&quot;">​</a></h2><p><strong>状态: v4.68.0 RELEASED; #19154, #19138 MERGED</strong></p><p><a href="https://github.com/langfuse/langfuse/releases/tag/v4.68.0" target="_blank" rel="noreferrer">v4.68.0</a> · <a href="https://github.com/langfuse/langfuse/pull/19154" target="_blank" rel="noreferrer">#19154</a> · <a href="https://github.com/langfuse/langfuse/pull/19138" target="_blank" rel="noreferrer">#19138</a></p><p>Gateway 新增连接级 socket 写入计数、阻塞与错误记录，以 connection_id 串起请求，并显式记录 output_complete；旧的 complete 只表示框架接受最后一块，不足以定位下游卡住。评分导出增加可选 metadata/provenance 字段，包括 evaluator、rule、queue 和执行 trace 等引用；默认导出不增加这些列。没有验证最终客户端完整接收或本地数据导出。</p><p><strong>为什么重要与 CodeFlowMu/FCoP 待验关联:</strong> 对 FCoP，状态词 complete 应绑定可观察层级；评分也需保留来源链，不能只有一个分数。</p><p><strong>互动判断与技术切入:</strong> 值得互动：如何把生成完整、socket 交付和客户端确认三种证据分层，而不合并成一个成功状态？</p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><ol><li><p>策略要绑定实际执行路径与当前授权。shell、apply_patch、tmux、MCP session 和独立构建容器都可能与表面配置不同；交付明确分配的密钥与隔离宿主秘密需要同时成立。</p></li><li><p>停止和恢复分别确认意图、剩余副作用与资源清理。普通退出、主动更新、headless 取消、后台清理及失败工作区重试不是同一状态迁移。</p></li><li><p>完成证据应分层并保留版本来源。trust-store、hook 脚本、恢复点、tool-call 参数流、socket 输出和评分 provenance 不能被一个成功标志替代。以上为本轮综合推断，不是各项目共同发布的标准。</p></li></ol><h2 id="双源核查、分类处置与覆盖说明" tabindex="-1">双源核查、分类处置与覆盖说明 <a class="header-anchor" href="#双源核查、分类处置与覆盖说明" aria-label="Permalink to &quot;双源核查、分类处置与覆盖说明&quot;">​</a></h2><ul><li>每轮首先通过已连接 GitHub 工具读取最新 main 的 <a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/REGISTRY.json" target="_blank" rel="noreferrer">Registry</a>：47 人，blob <code>8d97df65269aa2b4accd1366d1b71319f99c6efd</code>；并实读六位治理对象的<a href="https://github.com/joinwell52-AI/joinwell52/blob/main/research/intelligence/governance-researcher-repositories-2026-09-17.md" target="_blank" rel="noreferrer">关系边界</a>。人物、仓库、论文保持多对多，不把相关项目当论文官方实现。赵越始终采用正确中文名。</li><li>88 个去重仓库发起 commits、Release、Issue/PR 核查；87 个可读。TSA-AI-Workforce 三类端点仍返回 404，不猜测私有、删除或更名。共读取 492 条窗口仓库提交记录，含 Orca 追加页；59 个窗口无提交仓库另读当前默认分支 SHA。提交数不等于成果数。</li><li>高活跃 Issue/PR 追加到每源最多 12 页。Codex、Claude Code、Orca 均达到 1,200 条原始记录，仍未穷尽；前两者有少量翻页重叠，完整水位不推进。其余成功且翻页完成的来源才推进水位；更新时序不等于技术增量。</li><li>Release 常规读取最近 10 项；Codex 的大列表两次连接中断，改读最近 3 项及 latest 稳定版成功。稳定版仍为旧的 rust-v0.163.0，没有把本轮 main 合入写成新稳定版功能。列表是有界核查，不保证穷尽旧 Release 附件修改。</li><li>公开来源另外执行 12 组 Registry 人物/账号定向检索、官方工程页及 Python 安全公告核查。聚合站的本人帖转述未获得可靠原帖验证，不当作新增本人发言；不把搜索无结果等同于已读完 47 人时间线。</li><li>已读 <a href="https://cursor.com/changelog" target="_blank" rel="noreferrer">Cursor Changelog</a>、<a href="https://cursor.com/docs/release-notes/cloud-agents" target="_blank" rel="noreferrer">Cloud Agents release notes</a>、<a href="https://learn.chatgpt.com/docs/changelog" target="_blank" rel="noreferrer">OpenAI Changelog</a>、<a href="https://learn.chatgpt.com/docs/hooks" target="_blank" rel="noreferrer">官方 Hooks 文档</a>与 <a href="https://auditcommons.org/latest/" target="_blank" rel="noreferrer">Audit Commons</a>。Cursor 可见最新公告为 10 月 16 日、Cloud notes 为 10 月 5 日周、Audit Commons 最新条目为 10 月 18 日，均不重复算本轮新增。官方文档只作背景核对，抓取时间不等于发布日期。</li><li>双源是 GitHub 一手工程事实与另外的公开渠道核查，不要求每个 PR 都有本人社交重复证实，也不把两个 GitHub 链接当两种来源。六位治理对象继续跟踪所列仓库，不能由仓库无提交推断论文或社交无新增。</li><li>以前一轮本地记录和 10 月 22 日公开日档去重；昨天已报告的安装附件、已合入修复和 LiteLLM 事故不冒充新发现。本轮明确区分 SOURCE COMMIT、MERGED、OPEN、PRERELEASE 和 RELEASED；DSPy PR 正文中旧的待审提示不覆盖 GitHub 实际 merged 状态。</li><li>分类处置均为待验证线索、持续观察或资料留存；上游测试/验收不是本轮本地复现。本轮无实验完成、无文章生产、无正式开发评审、无开发派工、无外部评论或加星操作。互动栏只是技术议题，不公开评论稿、台账或回执。</li><li>日档源文件只更新规定的中英文当日报告和两个原样式索引。Research Runtime、Scheduler、Production/Publication、候选、文章和评分卡均不因本轮日档而修改；网站仅沿用原实现构建发布，并另核验真实入口、详情页和对应部署提交。</li></ul>',96)])])}const d=r(l,[["render",n]]);export{u as __pageData,d as default};
